/* The most operands any instruction has. */
#define EXARMO_AARCH32_MAX_OPERANDS 7

/* The most tokens any instruction is written as, and the most characters,
 * without the NUL. Buffers of these sizes hold whatever this release
 * decodes, so a caller that reserves them never has to ask for more. They
 * are worked out over every encoding's template, each operand counted at
 * the widest it is written, so they are an upper bound rather than a
 * measurement, and a later release may move them. */
#define EXARMO_AARCH32_MAX_TOKENS 84
#define EXARMO_AARCH32_MAX_TEXT 269

